// Compact quest selection: one stable list and one independently scrolling detail pane.
let guildBoardSelection=null;
function guildBoardQuests(region){let c=campaign(),r=REGIONS[region]||REGIONS[0];if(!c.questDone.length)return[guildQuest('hunt:r0e0')];let quests=[...r.enemies.map(s=>guildQuest('hunt:'+s.id)),...r.bosses.map(s=>guildQuest('boss:'+s.id))];if(c.rank<10&&r.id===c.rank-1)quests.unshift(guildQuest('trial:'+r.bosses[3].id));let secret=guildQuest('secret:'+r.secret.id);if(guildQuestAllowed(secret))quests.push(secret);quests.push(...EX_BOSSES.filter(s=>s.exRank<=c.rank).map(s=>guildQuest('ex:'+s.id)));return quests;}
function guildBoardDetail(q){let c=campaign(),allowed=guildQuestAllowed(q),kind={hunt:'討伐依頼',boss:'ボス討伐',trial:'昇格試験',secret:'裏ボス挑戦',ex:'EX討伐'}[q.kind],status=allowed?'A / クリックで受注':q.kind==='trial'?'受注まで あと '+Math.max(0,promotionXP(c.rank)-c.rankXP)+' ランクXP':'現在は受注できません';return'<small>'+kind+' · '+REGIONS[q.region].name+'</small><h3>'+q.name+'</h3><dl><div><dt>目標</dt><dd>'+SPECIES[q.target].name+' × '+q.required+'</dd></div><div><dt>報酬</dt><dd>'+q.xp+' ランクXP</dd></div></dl><p class="guild-selection-status">'+status+'</p>'+(q.kind==='trial'?'<p>報告すると次の地域と、この地域の裏ボス依頼が解放されます。</p>':q.kind==='ex'?'<p>HPを1%削るごとに欠片1個。討伐すると追加50個。</p>':q.kind==='secret'?'<p>昇格で解放された任意の強敵です。装備を整えて挑みましょう。</p>':'<p>指定の敵を倒し、村へ帰還して報告してください。</p>')+(c.questDone.includes(q.id)?'<small>再受注できます</small>':'');}
function inspectGuildQuest(id){let q=guildQuest(id),detail=$('guildQuestDetail');if(!q||!detail)return;guildBoardSelection=id;for(let button of $('card').querySelectorAll('[data-guild-quest]'))button.classList.toggle('guild-selected',button.dataset.guildQuest===id);detail.innerHTML=guildBoardDetail(q);detail.scrollTop=0;}
function activateGuildQuest(id){inspectGuildQuest(id);if(!guildQuestAllowed(guildQuest(id)))return false;return acceptGuildQuest(id);}
const compactGuildBase=showVillage;showVillage=(region=campaign().region)=>{
 let c=campaign();if(!villageOpen||c.contract)return compactGuildBase(region);let r=REGIONS[region]||REGIONS[0],quests=guildBoardQuests(r.id),selected=quests.find(q=>q.id===guildBoardSelection)||quests.find(q=>guildQuestAllowed(q))||quests[0];
 let xp=c.rank>=100?'最高ランク':c.rankXP+' / '+(c.rank<10?promotionXP(c.rank):veteranXP(c.rank));
 worldMenu('冒険者ギルド · ランク '+c.rank,'<div class="world-tabs"><button onclick="showForge()">素材工房</button><button onclick="showDps()">DPS訓練</button><button onclick="showJobHall()">転職所</button><button onclick="panel(\'inventory\')">装備</button>'+(c.lastEx?'<button onclick="showExResult()">前回のEX結果</button>':'')+'</div><label class="guild-region">地域 <select aria-label="探索地域" onchange="showVillage(+this.value)">'+REGIONS.map(x=>'<option value="'+x.id+'" '+(x.id===r.id?'selected':'')+' '+(x.id>c.unlocked?'disabled':'')+'>'+x.name+'</option>').join('')+'</select><span>ランクXP '+xp+'</span></label><div class="guild-board"><div class="guild-quest-list" aria-label="依頼一覧">'+quests.map(q=>'<button data-guild-quest="'+q.id+'" aria-describedby="guildQuestDetail" '+(!guildQuestAllowed(q)?'aria-disabled="true"':'')+' onfocus="inspectGuildQuest(\''+q.id+'\')" onclick="activateGuildQuest(\''+q.id+'\')">'+(!guildQuestAllowed(q)?'🔒 ':'')+q.name+'</button>').join('')+'</div><section id="guildQuestDetail" class="guild-quest-detail" aria-live="polite" aria-atomic="true"></section></div><details class="guild-story"><summary>物語・冒険者の手引き</summary><p>'+GUILD_STORY[r.id]+'</p><p>敵の素材を回収して工房で装備を製作。依頼を報告してランクXPをため、昇格試験へ。ランク10以降は経験値で昇格し、ランク20から10ごとにEXボスが解放されます。</p><button onclick="departRegion('+r.id+')" '+(r.id>c.unlocked?'disabled':'')+'>'+r.name+'を自由に探索</button></details>','village');
 inspectGuildQuest(selected.id);menuFocusElement($('card').querySelector('[data-guild-quest="'+selected.id+'"]'));
};
